<script setup lang="ts">
import {partnerError} from '@/utils/partnerError'
import {computed,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {importPreview,importMatches,importCommit,templateDownload,partnerOptions,partnerSave,newRequestId} from '@/api/modules/partner'
import {createCustomer} from '@/api/modules/customer'
import {createInventorySupplier} from '@/api/modules/supplier'
import PartnerFacts from './PartnerFacts.vue'
import OperationSpecPicker from './operations/OperationSpecPicker.vue'
import SharedCompatiblePhoneSelector from '@/views/mold/components/SharedCompatiblePhoneSelector.vue'
import type {BusinessData,PartnerKind,PartnerOptions,ImportPreview} from '@/types/partner'
const props=defineProps<{modelValue:boolean;kind:PartnerKind}>()
const emit=defineEmits<{(e:'update:modelValue',v:boolean):void;(e:'imported'):void}>()
const mappingDirty=ref(false)
const preview=ref<ImportPreview>(),busy=ref(false),error=ref(''),options=ref<PartnerOptions>()
const quick=ref(''),quickRow=ref<BusinessData>(),master=ref<BusinessData>({})
const open=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)})
const actionNames:Record<string,string>={new:'新建草稿',update:'更新资料，核对后保存',skip_same:'相同跳过',skip_confirmed:'已有确认订单，保留原历史',resolve:'待处理'}
watch(()=>props.modelValue,async v=>{if(v){preview.value=undefined;error.value='';options.value=await partnerOptions()}})
async function load(file:File){busy.value=true;error.value='';preview.value=undefined;try{preview.value=await importPreview(props.kind,file);mappingDirty.value=false}catch(e){error.value=partnerError(e)}finally{busy.value=false}return false}
async function check(){if(!preview.value)return;preview.value=await importMatches(props.kind,preview.value.token,preview.value.rows.map(r=>({rowNumber:r.rowNumber,supplierCode:r.supplierCode,customerId:r.customerId,specId:r.specId,...(props.kind==='partner-products'&&r.phoneModelIds!==undefined?{phoneModelIds:r.phoneModelIds}:{})})));mappingDirty.value=false}
async function commit(){busy.value=true;error.value='';try{if(mappingDirty.value){await check();ElMessage.info('匹配已核对，请检查结果后再次确认导入');return}if(!preview.value||preview.value.errorCount)throw Error('请先处理全部待匹配项与错误行');const result=await importCommit(props.kind,preview.value.token);ElMessage.success('已保存 '+result.saved+' 项，跳过 '+result.skipped+' 行');emit('imported');open.value=false}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
function specMatched(row:BusinessData,spec?:BusinessData){mappingDirty.value=true;if(props.kind==='partner-products')row.phoneModelIds=[...(spec?.details.phoneModelIds||[])]}
function newMaster(type:string,row:BusinessData){quick.value=type;quickRow.value=row;master.value={name:'',type:'unknown',contact:'',spec:row.values['规格']||'',phoneModelIds:[],supplierCode:row.supplierCode||''}}
async function saveMaster(){busy.value=true;try{if(quick.value==='customer'){const c=await createCustomer({customerName:master.value.name,customerType:master.value.type,contactName:master.value.contact,status:'draft',requestId:newRequestId()} as never);quickRow.value!.customerId=c.customerId}
else if(quick.value==='supplier'){const s=await createInventorySupplier({supplierName:master.value.name,supplierType:master.value.type,contactPerson:master.value.contact,supplyCategories:[],status:'draft',requestId:newRequestId()} as never);quickRow.value!.supplierCode=s.supplierCode}
else{const row=quickRow.value!;const p=await partnerSave('partner-products',{name:master.value.name,site:row.values['站点'],externalId:'',status:'draft',requestId:newRequestId(),specs:[{name:master.value.spec||'待确认',specification:master.value.spec,phoneModelIds:master.value.phoneModelIds,websiteSku:row.values['网站SKU']||'',sources:[{supplierCode:master.value.supplierCode,currency:row.values['币种']||'CNY'}]}]});quickRow.value!.specId=p.specs[0].id;quickRow.value!.supplierCode=master.value.supplierCode}
options.value=await partnerOptions();quick.value='';await check()}finally{busy.value=false}}
</script>
<template><el-dialog v-model="open" :title="kind==='partner-products'?'导入合作产品':'导入网站订单'" width="min(1000px,96vw)" :close-on-click-modal="false" append-to-body>
 <p class="import-tip">选择文件 → 匹配并核对 → 确认保存。已确认订单不会被导入覆盖，网站状态不会自动生成收款或发货。</p>
 <div class="import-tools"><el-button @click="templateDownload(kind,'xlsx')">XLSX 模板</el-button><el-button @click="templateDownload(kind,'csv')">CSV 模板</el-button><el-upload :show-file-list="false" :before-upload="load" accept=".csv,.xlsx"><el-button type="primary" :loading="busy">选择 CSV／XLSX</el-button></el-upload></div>
 <p v-if="preview">共 {{preview.rows.length}} 行 · 待处理 {{preview.errorCount}} 行</p><el-alert v-if="error" type="error" :title="error" :closable="false"/>
 <div class="import-rows"><article v-for="row in preview?.rows||[]" :key="row.rowNumber" class="import-row">
  <div><strong>第 {{row.rowNumber}} 行 · {{row.values['商品名称']||row.values['网站订单号']}}</strong><p>{{row.values['规格']||row.values['网站SKU']}} <template v-if="kind==='partner-sales'"> · {{row.values['数量']}} 件</template></p><el-tag :type="row.errors.length?'danger':row.action==='skip_confirmed'?'warning':'info'">{{actionNames[row.action]}}</el-tag><p v-if="row.errors.length" class="error">{{row.errors.join('；')}}</p></div>
  <div><label>匹配供方</label><el-select v-model="row.supplierCode" @change="mappingDirty=true" filterable clearable><el-option v-for="s in options?.suppliers||[]" :key="s.code" :value="s.code" :label="s.name+' · '+s.code"/></el-select><el-button link @click="newMaster('supplier',row)">＋ 单条新增供方</el-button>
   <template v-if="kind==='partner-sales'"><label>匹配客户</label><el-select v-model="row.customerId" @change="mappingDirty=true" filterable clearable><el-option v-for="c in options?.customers||[]" :key="c.customerId" :value="c.customerId" :label="c.customerName+' · '+c.customerCode"/></el-select><el-button link @click="newMaster('customer',row)">＋ 单条新增客户</el-button></template>
  </div>
  <div><label>{{kind==='partner-products'?'已有规格（空为新建）':'匹配商品规格'}}</label><OperationSpecPicker v-model="row.specId" :supplier-code="kind==='partner-sales' ? row.supplierCode || undefined : undefined" active-only :aria-label="`第 ${row.rowNumber} 行匹配商品规格`" @selected="specMatched(row,$event)"/><el-button v-if="kind==='partner-sales'" link @click="newMaster('product',row)">＋ 单条新增产品</el-button><template v-if="kind==='partner-products'"><label>适配机型</label><SharedCompatiblePhoneSelector v-model="row.phoneModelIds" placeholder="从系统机型库选择，可搜索、多选" aria-label="导入适配机型" @update:model-value="mappingDirty=true"/></template><p class="muted">来源：{{row.values['站点']}} · {{row.values['网站SKU']||row.values['网站商品号']||'未填外部编号'}}</p><details v-if="row.existingId"><summary>原记录与来源差异</summary><PartnerFacts v-if="row.changes?.length" :value="row.changes"/><p>已有记录 {{row.existingId}} · 确认历史保留。本次来源状态：{{row.values['网站来源状态']||'未填'}}。</p><p v-if="options?.canReadMoney">本次来源单价：{{row.values['单价']||row.values['参考单价']||'未填'}} {{row.values['币种']}}</p></details></div>
 </article></div>
 <template #footer><el-button @click="open=false">取消</el-button><el-button :disabled="!preview" @click="check">重新核对匹配</el-button><el-button type="primary" :disabled="!preview" :loading="busy" @click="commit">确认导入</el-button></template>
 <el-dialog :model-value="Boolean(quick)" title="单条新增，保存后返回匹配" width="min(480px,94vw)" append-to-body @close="quick=''"><el-form label-position="top"><el-form-item label="常用名称 *"><el-input v-model="master.name"/></el-form-item><template v-if="quick!=='product'"><el-form-item label="类型"><el-select v-model="master.type"><el-option label="待补充" value="unknown"/><el-option label="公司" value="company"/><el-option label="个人" value="person"/></el-select></el-form-item><el-form-item label="联系方式（可后补）"><el-input v-model="master.contact"/></el-form-item></template><template v-else><el-form-item label="适配机型"><SharedCompatiblePhoneSelector v-model="master.phoneModelIds" placeholder="从系统机型库选择，可搜索、多选" aria-label="新增产品适配机型"/></el-form-item><el-form-item label="规格补充（选填）"><el-input v-model="master.spec" placeholder="如透明、黑色、TPU"/></el-form-item><el-form-item label="供方"><el-select v-model="master.supplierCode" filterable><el-option v-for="s in options?.suppliers||[]" :key="s.code" :value="s.code" :label="s.name"/></el-select></el-form-item></template></el-form><template #footer><el-button @click="quick=''">取消</el-button><el-button type="primary" :loading="busy" @click="saveMaster">保存并返回</el-button></template></el-dialog>
 </el-dialog></template>
<style scoped>.import-tools{display:flex;gap:8px;flex-wrap:wrap}.import-tip,.muted{color:#7687a0;font-size:12px;line-height:1.7}.import-rows{max-height:55vh;overflow:auto}.import-row{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:16px;padding:15px 0;border-bottom:1px solid #e7ecf4}.import-row>div{min-width:0;overflow-wrap:anywhere}.import-row label{display:block;margin:7px 0;color:#6a7b94;font-size:12px}.import-row .el-select{width:100%}.error{color:#bc4c4c;font-size:12px}summary{cursor:pointer}@media(max-width:700px){.import-row{grid-template-columns:1fr}}</style>
